import{_ as o,l as n,o as e,c as s,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"事务 ACID","description":"","frontmatter":{"title":"事务 ACID","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/acid.md","filePath":"cs/acid.md","lastUpdated":1789023840000}'),A={name:"cs/acid.md"};function h(E,a,D,m,_,C){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="事务-acid" tabindex="-1">事务 ACID <a class="header-anchor" href="#事务-acid" aria-label="Permalink to &quot;事务 ACID&quot;">​</a></h1><div class="epigraph"><p>原子、一致、隔离、持久把「一次业务步骤」收成失败可撤、成功则永在的单位。</p><footer>—— 据 Haerder and Reuter, Principles of Transaction-Oriented Database Recovery, CSUR 1983；Gray and Reuter</footer></div><p><a href="/cs/checkpoint">上一课</a>保证崩溃后日志能把页拉回一致的物理状态。本课不重做 CLR。缺口是：用户看到的不是页，而是<strong>事务</strong>——一组读写要么都发生，要么都不发生。ACID 四字把恢复、完整性、并发与持久绑在同一个接口上；每一字的机制已经或即将由邻课承担，本课负责命名与分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次转账是两次更新。进程可以在中间被杀，并发可以交错，约束可以暂时假。缺口不是再讲 WAL，而是把工作单位说清：<strong>A</strong> 原子：没有「只扣了一边」；<strong>C</strong> 一致：提交后满足声明的完整性；<strong>I</strong> 隔离：并发看起来像某种串行；<strong>D</strong> 持久：提交后崩溃仍在。没有这个单位，应用只能自己在套接字与文件上拼补偿。</p><p><span class="marginnote">Haerder and Reuter 1983 把 recovery 与 ACID 放在同一篇文章里讲。C 在他们那里偏完整性约束；隔离的精确数学是后课冲突可串行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事务：begin 到 commit/abort。原子与持久靠 WAL + ARIES：commit 记录刷盘则 D 成立，abort 或崩溃走 UNDO 得 A。一致靠<a href="/cs/keys-integrity">键与完整性</a>在事务边界检查——可以允许事务内部暂时违例，提交时必须真。隔离下一课才用冲突图；本课只声明需要一个并发正确性标准。</p>',8)),(e(),l(c,null,{default:t(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E4%BA%8B%E5%8A%A1%22%5D%20--%3E%20A%5B%22%E5%8E%9F%E5%AD%90%3A%20UNDO%22%5D%0A%20%20TX%20--%3E%20D%5B%22%E6%8C%81%E4%B9%85%3A%20%E6%97%A5%E5%BF%97%E5%B7%B2%E5%88%B7%22%5D%0A%20%20TX%20--%3E%20C%5B%22%E6%8F%90%E4%BA%A4%E6%97%B6%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20TX%20--%3E%20I%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%86%B2%E7%AA%81%E5%8F%AF%E4%B8%B2%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ACID 是规格，不是一种算法。实现可以锁、可以多版本、可以单线程串行。D 不要求数据页已刷，只要求日志已刷——<a href="/cs/wal">WAL</a>已说。A 不要求执行时没有脏页，只要求对外从不展示半成品提交。C 不能单靠恢复：恢复只回到「约束曾被承诺的状态」，若应用逻辑本身写错，C 仍假。</p><p>本课不把「BASE」「最终一致」写成 ACID 的对立宗教；那些是后课隔离级别与分布式下的显式放松。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 ACID 当成「数据库很慢的原因」。每一字都可以用不同强度实现。也不要在本课展开脏读、幻读——那是隔离级别课用异常命名的缺口。分布式下 D 与 A 还要跨节点，入口在两阶段提交。</p><p>单语句自动提交也是事务，只是边界与语句重合；没有 begin 不等于没有 A/D。后课默认：谈到事务，四字已分工；并发正确性从冲突可串行讲起，而不是从「锁住一切」讲起。</p><p>四字拆开之后，实现可以换：A/D 用日志，I 用锁或版本，C 用约束。用户接口仍是 begin/commit/abort。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>没有隔离标准之前，「并发正确」没有对象；下一课用冲突图给尺子。</p></li><li><p>约束可以推迟到提交时检查，那是 C 与 I 的交界，不是 WAL 的事。</p></li><li><p>恢复已能 REDO/UNDO；本课把用户单位命名为事务并拆开 ACID。</p></li><li><p>A/D 靠日志；C 靠约束；I 尚未给出调度标准。</p></li><li><p>冲突可串行是隔离的第一根尺子。</p></li><li><p>出处：Haerder and Reuter, 1983；Gray and Reuter, <em>Transaction Processing</em>。</p></li></ul>',9))])}const B=o(A,[["render",h]]);export{f as __pageData,B as default};
